"""Controller-only fixtures and a factory EEPROM generated by the emulated game."""

from pathlib import Path
import hashlib
import json
import os
import re
import shutil
import subprocess

HERE = Path(__file__).resolve().parent
IDENTITIES = json.loads((HERE / "fixtures/recordings.json").read_text())
FACTORY_SHA256 = "08a9266d2a6097e116562a74c0adfe5702f36028d76679bc8297664e8f7bb187"
DEFAULT_RECORDINGS = Path(os.environ.get("GLES3_TEST_RECORDINGS", HERE / "recordings"))


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def host_environment(cache):
    env = {k: v for k, v in os.environ.items() if not k.startswith(("RR_", "SND_", "ENG_"))}
    env.pop("LD_PRELOAD", None)
    env.update(
        SDL_VIDEODRIVER="offscreen",
        SDL_AUDIODRIVER="dummy",
        LP_NUM_THREADS="1",
        ENG_GLES3_HOST="1",
        ENG_GLES3_ASSETS=str(cache.resolve()),
    )
    return env


def generate_eeprom(binary, roms, cache, output, *, calibrated=False):
    """Boot all-ones EEPROM; optionally let the ROM calibrate the analogue inputs."""
    env = host_environment(cache)
    env["ENG_GLES3_FACTORY_EEPROM"] = str(output.resolve())
    command = [str(binary.resolve()), str(roms.resolve()), "--frames", "600", "--audio", "off", "--overlay", "off"]
    expected = FACTORY_SHA256
    if calibrated:
        # The ROM service adjustment samples centred steering and released pedals.
        # Leave TEST to let the game's own EEPROM writer persist calibration.
        rec = output.with_suffix(".calibration.rec")
        rec.write_text(
            "F 1 FEFF 800 000 000\nF 1000 F2FF 800 000 000\n" "F 1100 FAFF 800 000 000\nF 1200 FEFF 800 000 000\n"
        )
        blank = bytes([255]) * 8192
        checksum = 14695981039346656037
        for byte in blank:
            checksum = ((checksum ^ byte) * 1099511628211) & ((1 << 64) - 1)
        Path(str(rec) + ".eeprom").write_bytes(blank)
        Path(str(rec) + ".end").write_text("1600\n")
        metadata = (HERE / "recordings/full-race.rec.meta").read_text()
        old = re.search(r"EEPROM ([0-9a-f]{16})", metadata)[1]
        Path(str(rec) + ".meta").write_text(metadata.replace(old, f"{checksum:016x}"))
        command = [str(binary.resolve()), str(roms.resolve()), "--replay-input", str(rec.resolve())]
        expected = IDENTITIES["full-race"]["eeprom_sha256"]
    with output.with_suffix(".log").open("w") as log:
        subprocess.run(
            command,
            env=env,
            check=True,
            stdout=log,
            stderr=log,
        )
    log_text = output.with_suffix(".log").read_text()
    if "[SND] TRANSLATED DRIVER" in log_text or "GLES3 UNSUPPORTED" in log_text:
        raise RuntimeError("Factory boot trapped; see factory log")
    actual = sha(output)
    if actual != expected:
        raise RuntimeError(f"Factory EEPROM mismatch: expected {expected}, got {actual}; no stored seed allowed")
    return output.resolve()


def prepare_recording(name, source, output, eeprom):
    """Materialize runtime sidecars outside Git; recorded metadata remains checked."""
    identity = IDENTITIES[name]
    recording = source / (name + ".rec")
    if sha(recording) != identity["input_sha256"]:
        raise RuntimeError(f"Input recording SHA256 mismatch: {recording}")
    if sha(eeprom) != identity["eeprom_sha256"]:
        raise RuntimeError("Generated initial EEPROM SHA256 mismatch")
    output.mkdir(exist_ok=True)
    target = output / recording.name
    shutil.copyfile(recording, target)
    # SHA-pinned inputs always use the committed, generated-EEPROM reset recipe.
    # An override directory needs controller files only, never old seed sidecars.
    for suffix in (".meta", ".end"):
        metadata = HERE / "recordings" / (name + ".rec" + suffix)
        shutil.copyfile(metadata, Path(str(target) + suffix))
    if Path(str(target) + ".end").read_text().strip() != str(identity["ticks"]):
        raise RuntimeError("Recording length metadata mismatch")
    shutil.copyfile(eeprom, Path(str(target) + ".eeprom"))
    return target.resolve()
